'use strict';

function _isPositiveFinite(value) {
  return typeof value === 'number' && isFinite(value) && value > 0;
}

function _isNonNegativeFinite(value) {
  return typeof value === 'number' && isFinite(value) && value >= 0;
}

class TokenBucket {
  constructor({ capacity, refillPerSecond, now } = {}) {
    if (!_isPositiveFinite(capacity)) {
      throw new RangeError('capacity must be a positive finite number');
    }
    if (!_isNonNegativeFinite(refillPerSecond)) {
      throw new RangeError('refillPerSecond must be a non-negative finite number');
    }

    this.capacity = capacity;
    this.refillPerSecond = refillPerSecond;
    this.nowFn = typeof now === 'function' ? now : Date.now;
    this.tokens = capacity;
    this.lastTime = this.nowFn();
  }

  _refill() {
    const current = this.nowFn();
    if (current >= this.lastTime) {
      const elapsedMs = current - this.lastTime;
      this.tokens = Math.min(
        this.capacity,
        this.tokens + (elapsedMs / 1000) * this.refillPerSecond
      );
      this.lastTime = current;
    }
    // Saat geri giderse jeton eklenmez/çıkarılmaz ve o ana kadar görülen
    // en büyük zaman referans (lastTime) korunur.
  }

  available() {
    this._refill();
    return this.tokens;
  }

  tryTake(n = 1) {
    if (!_isPositiveFinite(n)) {
      throw new RangeError('n must be a positive finite number');
    }
    this._refill();
    if (this.tokens >= n) {
      this.tokens -= n;
      return true;
    }
    return false;
  }

  msUntil(n = 1) {
    if (!_isPositiveFinite(n)) {
      throw new RangeError('n must be a positive finite number');
    }
    this._refill();
    if (this.tokens >= n) {
      return 0;
    }
    if (n > this.capacity) {
      return Infinity;
    }
    if (this.refillPerSecond <= 0) {
      return Infinity;
    }
    const needed = n - this.tokens;
    const ms = (needed / this.refillPerSecond) * 1000;
    return Math.ceil(ms);
  }
}

module.exports = { TokenBucket };

const { TokenBucket } = require('./kova.js');

// Basic test
let b = new TokenBucket({ capacity: 10, refillPerSecond: 5 });
console.log('initial available:', b.available()); // 10
console.log('tryTake(3):', b.tryTake(3)); // true
console.log('available after take:', b.available()); // 7
console.log('tryTake(100):', b.tryTake(100)); // false
console.log('available unchanged:', b.available()); // 7

// Refill with fake time
let t = 1000;
b = new TokenBucket({ capacity: 10, refillPerSecond: 10, now: () => t });
console.log('available at t=1000:', b.available()); // 10
b.tryTake(10);
console.log('available after take 10:', b.available()); // 0
t = 1500; // 0.5s later, +5 tokens
console.log('available at t=1500:', b.available()); // 5
console.log('msUntil(6):', b.msUntil(6)); // ceil((6-5)/10*1000) = 100
console.log('tryTake(6):', b.tryTake(6)); // false

t = 1600; // +1 more token = 6
console.log('available at t=1600:', b.available()); // 6
console.log('tryTake(6):', b.tryTake(6)); // true
console.log('available after:', b.available()); // 0

// Time goes backward - tokens should not change
t = 1000; // goes back
console.log('available after time back:', b.available()); // 0 (no change, lastTime stays 1600)

// n > capacity => Infinity
console.log('msUntil(20) when capacity=10:', b.msUntil(20)); // Infinity

// refillPerSecond = 0 and not enough tokens
b = new TokenBucket({ capacity: 5, refillPerSecond: 0, now: () => 1000 });
b.tryTake(5);
console.log('msUntil(1) with refill 0:', b.msUntil(1)); // Infinity

// RangeError tests
try { new TokenBucket({ capacity: 0, refillPerSecond: 1 }); } catch (e) { console.log('capacity 0:', e instanceof RangeError, e.message); }
try { new TokenBucket({ capacity: 10, refillPerSecond: -1 }); } catch (e) { console.log('refill -1:', e instanceof RangeError, e.message); }
try { b.tryTake(0); } catch (e) { console.log('tryTake(0):', e instanceof RangeError, e.message); }
try { b.msUntil(-5); } catch (e) { console.log('msUntil(-5):', e instanceof RangeError, e.message); }
try { b.tryTake(Infinity); } catch (e) { console.log('tryTake(Infinity):', e instanceof RangeError, e.message); }

console.log('All tests passed');
